pub struct LoadWorkUseCase {
    uow_factory: Box<dyn LoadWorkUnitOfWorkFactoryTrait>,
}

impl LoadWorkUseCase {
    pub fn new(uow_factory: Box<dyn LoadWorkUnitOfWorkFactoryTrait>) -> Self {
        LoadWorkUseCase { uow_factory }
    }

    pub fn execute(&mut self, dto: &LoadWorkDto) -> Result<()> {
        let now = chrono::Utc::now();

        // Stage 1: read + map the file into a neutral graph (no store access yet).
        let shape = skrib::detect_shape(&dto.file_name)
            .with_context(|| format!("inspecting '{}'", dto.file_name))?;
        let loaded = match shape {
            SkribShape::LegacySqlite => {
                let project = legacy::read_project(&dto.file_name)
                    .with_context(|| format!("reading legacy project '{}'", dto.file_name))?;
                legacy_to_loaded(project, now)
            }
            SkribShape::ZipFile | SkribShape::ExplodedFolder => {
                let bundle = skrib::read_bundle(&dto.file_name)
                    .with_context(|| format!("reading project '{}'", dto.file_name))?;
                skrib::bundle_to_loaded(bundle, &dto.file_name)?
            }
        };

        // Stage 2: materialise entities in a single transaction. First close the
        // currently-open work (no-op on a fresh store) — opening a work replaces
        // it. Shared helper, NOT a use-case call (use cases never call each other).
        let mut uow = self.uow_factory.create();
        uow.begin_transaction()?;

        work_io::close_current_work(&*uow)?;

        let mat = materialize(&*uow, &loaded)?;
        create_trunk(&*uow, &loaded, &mat, &dto.file_name, shape, now)?;

        uow.commit()?;
        uow.publish_load_work_event(vec![mat.work_id], None);
        Ok(())
    }
}

struct Materialized {
    work_id: EntityId,
    trash_info_ids: Vec<EntityId>,
}

/// Materialise the Work subtree (lossless: every scalar field, content row,
/// ordering and M2M link is preserved; file ids are remapped to fresh store ids).
fn materialize(uow: &dyn LoadWorkUnitOfWorkTrait, loaded: &LoadedWork) -> Result<Materialized> {
    let lw = &loaded.work;
    let work = uow.create_orphan_work(&Work {
        created_at: lw.created_at,
        updated_at: lw.updated_at,
        title: lw.title.clone(),
        author_name: lw.author_name.clone(),
        dict_language: lw.dict_language.clone(),
        // Single heal point for every load (legacy + new-format): preserve the
        // source's stable id, or mint a fresh one when it has none.
        unique_id: if lw.unique_id.is_empty() {
            crate::work_io::new_unique_id()
        } else {
            lw.unique_id.clone()
        },
        ..Default::default()
    })?;

    // Tags (file id -> new id).
    let mut tag_map: HashMap<u64, EntityId> = HashMap::new();
    let mut tag_ids: Vec<EntityId> = Vec::new();
    for t in &loaded.tags {
        let created = uow.create_orphan_binder_tag(&BinderTag {
            created_at: t.created_at,
            updated_at: t.updated_at,
            name: t.name.clone(),
            color: t.color.clone(),
            text_color: t.text_color.clone(),
            ..Default::default()
        })?;
        tag_map.insert(t.id, created.id);
        tag_ids.push(created.id);
    }

    // Dictionary words.
    let mut dict_word_ids: Vec<EntityId> = Vec::new();
    for w in &loaded.dict_words {
        let created = uow.create_orphan_dict_word(&DictWord {
            created_at: w.created_at,
            updated_at: w.updated_at,
            word: w.word.clone(),
            ..Default::default()
        })?;
        dict_word_ids.push(created.id);
    }

    // Binders -> items -> contents.
    let mut binder_map: HashMap<u64, EntityId> = HashMap::new();
    let mut item_map: HashMap<u64, EntityId> = HashMap::new();
    let mut binder_ids: Vec<EntityId> = Vec::new();
    let mut item_tag_links: Vec<(EntityId, Vec<u64>)> = Vec::new();

    for lb in &loaded.binders {
        let created_binder = uow.create_orphan_binder(&Binder {
            created_at: lb.binder.created_at,
            updated_at: lb.binder.updated_at,
            name: lb.binder.name.clone(),
            activated: lb.binder.activated,
            ..Default::default()
        })?;
        binder_map.insert(lb.binder.id, created_binder.id);

        let mut item_ids: Vec<EntityId> = Vec::new();
        for li in &lb.items {
            let mut content_ids: Vec<EntityId> = Vec::new();
            for c in &li.contents {
                let created_content = uow.create_orphan_content(&Content {
                    created_at: c.created_at,
                    updated_at: c.updated_at,
                    activated: c.activated,
                    role: c.role.clone(),
                    data: c.data.clone(),
                    ..Default::default()
                })?;
                content_ids.push(created_content.id);
            }

            let i = &li.item;
            let created_item = uow.create_orphan_binder_item(&BinderItem {
                created_at: i.created_at,
                updated_at: i.updated_at,
                title: i.title.clone(),
                sub_title: i.sub_title.clone(),
                role: i.role.clone(),
                sub_role: i.sub_role.clone(),
                label: i.label.clone(),
                activated: i.activated,
                is_favorite: i.is_favorite,
                is_printable: i.is_printable,
                indent: i.indent,
                word_count_goal: i.word_count_goal,
                char_count_goal: i.char_count_goal,
                dict_language: i.dict_language.clone(),
                ..Default::default()
            })?;

            if !content_ids.is_empty() {
                uow.set_binder_item_relationship(
                    &created_item.id,
                    &BinderItemRelationshipField::Contents,
                    &content_ids,
                )?;
            }
            item_map.insert(li.item.id, created_item.id);
            if !li.tag_ids.is_empty() {
                item_tag_links.push((created_item.id, li.tag_ids.clone()));
            }
            item_ids.push(created_item.id);
        }

        uow.set_binder_relationship(
            &created_binder.id,
            &BinderRelationshipField::BinderItems,
            &item_ids,
        )?;
        binder_ids.push(created_binder.id);
    }

    // M2M item tags (remap file tag ids -> store ids).
    for (item_id, file_tag_ids) in &item_tag_links {
        let resolved: Vec<EntityId> = file_tag_ids
            .iter()
            .filter_map(|t| tag_map.get(t).copied())
            .collect();
        if !resolved.is_empty() {
            uow.set_binder_item_relationship(
                item_id,
                &BinderItemRelationshipField::Tags,
                &resolved,
            )?;
        }
    }

    // M2M self-references (cross-links), grouped by source.
    let mut refs_by_source: HashMap<EntityId, Vec<EntityId>> = HashMap::new();
    for (src, dst) in &loaded.references {
        if let (Some(&s), Some(&d)) = (item_map.get(src), item_map.get(dst)) {
            refs_by_source.entry(s).or_default().push(d);
        }
    }
    for (s, dsts) in &refs_by_source {
        uow.set_binder_item_relationship(s, &BinderItemRelationshipField::References, dsts)?;
    }

    // Trash index (remap origin + trashed targets).
    let mut trash_info_ids: Vec<EntityId> = Vec::new();
    for t in &loaded.trash_infos {
        let origin = if t.origin_binder_id == 0 {
            0
        } else {
            binder_map
                .get(&(t.origin_binder_id as u64))
                .copied()
                .map(|v| v as i64)
                .unwrap_or(0)
        };
        let info = uow.create_orphan_trash_info(&TrashInfo {
            created_at: t.created_at,
            updated_at: t.updated_at,
            trashed_at: t.trashed_at,
            origin_binder_id: origin,
            ..Default::default()
        })?;
        if let Some(b) = t.trashed_binder.and_then(|b| binder_map.get(&b).copied()) {
            uow.set_trash_info_relationship(
                &info.id,
                &TrashInfoRelationshipField::TrashedBinder,
                &[b],
            )?;
        }
        if let Some(it) = t
            .trashed_binder_item
            .and_then(|i| item_map.get(&i).copied())
        {
            uow.set_trash_info_relationship(
                &info.id,
                &TrashInfoRelationshipField::TrashedBinderItem,
                &[it],
            )?;
        }
        trash_info_ids.push(info.id);
    }

    // Work's owned collections.
    uow.set_work_relationship(&work.id, &WorkRelationshipField::Binders, &binder_ids)?;
    if !tag_ids.is_empty() {
        uow.set_work_relationship(&work.id, &WorkRelationshipField::Tags, &tag_ids)?;
    }
    if !dict_word_ids.is_empty() {
        uow.set_work_relationship(&work.id, &WorkRelationshipField::DictWords, &dict_word_ids)?;
    }

    Ok(Materialized {
        work_id: work.id,
        trash_info_ids,
    })
}

/// Build the non-undoable trunk: System + RecentWork + WorkInfo (records the
/// opened path and its shape) + Root.
fn create_trunk(
    uow: &dyn LoadWorkUnitOfWorkTrait,
    loaded: &LoadedWork,
    mat: &Materialized,
    file_name: &str,
    shape: SkribShape,
    now: DateTime<Utc>,
) -> Result<()> {
    let system = uow.create_orphan_system(&System {
        created_at: now,
        updated_at: now,
        ..Default::default()
    })?;
    let recent = uow.create_orphan_recent_work(&RecentWork {
        created_at: now,
        updated_at: now,
        title: loaded.work.title.clone(),
        last_opened_at: now,
        absolute_path: loaded.absolute_path.clone(),
        ..Default::default()
    })?;
    uow.set_system_relationship(
        &system.id,
        &SystemRelationshipField::RecentWorks,
        &[recent.id],
    )?;

    let work_shape = match shape {
        SkribShape::ExplodedFolder => WorkShape::Folder,
        SkribShape::ZipFile | SkribShape::LegacySqlite => WorkShape::Zip,
    };
    let work_info = uow.create_orphan_work_info(&WorkInfo {
        created_at: now,
        updated_at: now,
        file_name: Some(file_name.to_string()),
        shape: work_shape,
        ..Default::default()
    })?;
    uow.set_system_relationship(
        &system.id,
        &SystemRelationshipField::WorkInfo,
        &[work_info.id],
    )?;

    if !mat.trash_info_ids.is_empty() {
        uow.set_system_relationship(
            &system.id,
            &SystemRelationshipField::TrashInfos,
            &mat.trash_info_ids,
        )?;
    }

    let root = uow.create_orphan_root(&Root {
        created_at: now,
        updated_at: now,
        ..Default::default()
    })?;
    uow.set_root_relationship(&root.id, &RootRelationshipField::System, &[system.id])?;
    uow.set_root_relationship(&root.id, &RootRelationshipField::Works, &[mat.work_id])?;
    Ok(())
}

/// Adapt the legacy SQLite reader's output to the neutral graph, assigning
/// internally-consistent file ids and reproducing the historic defaults
/// (`is_printable = true`, trashed items stay in place indexed by TrashInfo).
fn legacy_to_loaded(p: legacy::LegacyProject, now: DateTime<Utc>) -> LoadedWork {
    use skrib::{LoadedBinder, LoadedItem, LoadedTrash};

    let mut next_id: u64 = 1;
    let mut fresh = || {
        let v = next_id;
        next_id += 1;
        v
    };

    let work = Work {
        id: fresh(),
        created_at: now,
        updated_at: now,
        title: p.title.clone(),
        author_name: p.author.clone(),
        dict_language: p.dict_language.clone(),
        // Carry the legacy id through; empty → minted at `materialize`.
        unique_id: p.unique_id.clone(),
        ..Default::default()
    };

    let mut tag_map: HashMap<i64, u64> = HashMap::new();
    let tags: Vec<BinderTag> = p
        .tags
        .iter()
        .map(|(old, t)| {
            let fid = fresh();
            tag_map.insert(*old, fid);
            BinderTag {
                id: fid,
                created_at: now,
                updated_at: now,
                name: t.name.clone(),
                color: t.color.clone(),
                text_color: t.text_color.clone(),
            }
        })
        .collect();

    let dict_words: Vec<DictWord> = p
        .dict_words
        .iter()
        .map(|w| DictWord {
            id: fresh(),
            created_at: now,
            updated_at: now,
            word: w.clone(),
        })
        .collect();

    let mut item_map: HashMap<i64, u64> = HashMap::new();
    let mut trash_infos: Vec<LoadedTrash> = Vec::new();
    let mut binders: Vec<LoadedBinder> = Vec::new();

    for b in &p.binders {
        let bfid = fresh();
        if !b.activated {
            trash_infos.push(LoadedTrash {
                created_at: now,
                updated_at: now,
                trashed_at: now,
                origin_binder_id: 0,
                trashed_binder: Some(bfid),
                trashed_binder_item: None,
            });
        }

        let mut items: Vec<LoadedItem> = Vec::new();
        for it in &b.items {
            let ifid = fresh();
            item_map.insert(it.old_id, ifid);

            let contents: Vec<Content> = it
                .contents
                .iter()
                .map(|c| Content {
                    id: fresh(),
                    created_at: now,
                    updated_at: now,
                    activated: it.activated,
                    role: c.role.clone(),
                    data: c.data.clone(),
                })
                .collect();

            if !it.activated {
                trash_infos.push(LoadedTrash {
                    created_at: now,
                    updated_at: now,
                    trashed_at: now,
                    origin_binder_id: bfid as i64,
                    trashed_binder: None,
                    trashed_binder_item: Some(ifid),
                });
            }

            let tag_ids: Vec<u64> = it
                .tag_old_ids
                .iter()
                .filter_map(|t| tag_map.get(t).copied())
                .collect();

            items.push(LoadedItem {
                item: BinderItem {
                    id: ifid,
                    created_at: now,
                    updated_at: now,
                    title: it.title.clone(),
                    sub_title: it.sub_title.clone(),
                    role: it.role.clone(),
                    sub_role: it.sub_role.clone(),
                    label: it.label.clone(),
                    activated: it.activated,
                    is_printable: true,
                    indent: it.indent,
                    ..Default::default()
                },
                contents,
                tag_ids,
            });
        }

        binders.push(LoadedBinder {
            binder: Binder {
                id: bfid,
                created_at: now,
                updated_at: now,
                name: b.name.clone(),
                activated: b.activated,
                ..Default::default()
            },
            items,
        });
    }

    let references: Vec<(u64, u64)> = p
        .references
        .iter()
        .filter_map(
            |(src, dst)| match (item_map.get(src).copied(), item_map.get(dst).copied()) {
                (Some(s), Some(d)) => Some((s, d)),
                _ => None,
            },
        )
        .collect();

    LoadedWork {
        work,
        tags,
        dict_words,
        binders,
        trash_infos,
        references,
        absolute_path: p.absolute_path.clone(),
    }
}
